380	/**
381	 * Gives an opening claim its number. While the sheet's period numbering from is set and the sheet's
382	 * today is on or after it, the number counts from 1 within the claim's period: {@code <period>-<n>},
383	 * or {@code X-<n>} in its own sequence for a claim in no period. Otherwise it is the sheet-wide number,
384	 * whose sequence only the claims numbered sheet-wide advance.
385	 */
386	@Repository
387	public class ClaimNumbering {
388	    /** The prefix of the sequence of claims whose due-by is in no period. */
389	    public static final String NO_PERIOD = "X";
390	    private final JdbcTemplate jdbc;
391	    private final Sheets sheets;
392	    private final Settings settings;
393	    private final Periods periods;
394	    public ClaimNumbering(JdbcTemplate jdbc, Sheets sheets, Settings settings, Periods periods) {
395	        this.jdbc = jdbc;
396	        this.sheets = sheets;
397	        this.settings = settings;
398	        this.periods = periods;
399	    }
400	    /** Whether claims are numbered within their period now: the period numbering from is set and the sheet's today is on or after it. */
401	    public boolean perPeriod(String sheetId) {
402	        LocalDate from = settings.periodNumberingFrom(sheetId);
403	        return from != null && !sheets.today(sheetId).isBefore(from);
404	    }
405	    /** The next number for a claim dated on the date, opened now. */
406	    public String next(String sheetId, LocalDate claimDate) {
407	        if (!perPeriod(sheetId)) {
408	            return String.valueOf(sheets.nextClaimNumber(sheetId));
409	        }
410	        String period = periods.nameOn(sheetId, claimDate);
411	        String key = period == null ? "" : period;
412	        // Lock the sheet's row so claims opened at the same moment get distinct numbers.
413	        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", (rs, i) -> rs.getString(1), sheetId);
414	        jdbc.update("MERGE INTO period_claim_number (sheet_id, period_name, last_number) KEY (sheet_id, period_name)"
415	                + " VALUES (?, ?, COALESCE((SELECT last_number FROM period_claim_number WHERE sheet_id = ? AND period_name = ?), 0) + 1)",
416	                sheetId, key, sheetId, key);
417	        Long n = jdbc.queryForObject("SELECT last_number FROM period_claim_number WHERE sheet_id = ? AND period_name = ?",
418	                Long.class, sheetId, key);
419	        return (period == null ? NO_PERIOD : period) + "-" + n;
420	    }
