424	    private static final Pattern AMOUNT = Pattern.compile("\\d+(\\.\\d{1,2})?");
425	    private static final Pattern SIGNED_AMOUNT = Pattern.compile("-?\\d+(\\.\\d{1,2})?");
426	    private static final Pattern NUMBER = Pattern.compile("\\d+|\\S+-\\d+");
427	    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody ClaimRequest request, Out<ValidClaim> body, Settings settings)
428	            throws InvalidClaimException, ViewerRefusedException {
429	        settings.refuseViewer(sheetId, request.user());
430	        body.set(check(request));
431	    }
432	    /** The claim form's rules on its body alone; the sheet's rules are checked when the claim is saved. */
433	    static ValidClaim check(ClaimRequest request) throws InvalidClaimException {
434	        BigDecimal amount = signedAmount(request.amount());
435	        String corrects = corrects(request.corrects());
436	        if (amount.signum() < 0 && corrects == null) {
437	            throw new InvalidClaimException("A negative amount is a correction: it must name the claim it corrects");
438	        }
439	        if (amount.signum() >= 0 && corrects != null) {
440	            throw new InvalidClaimException("Only a correction (a negative amount) can name a claim it corrects");
441	        }
442	        String rawDate = request.date() == null ? "" : request.date().trim();
443	        LocalDate date = null;
444	        if (!rawDate.isEmpty()) {
445	            try {
446	                date = LocalDate.parse(rawDate);
447	            } catch (DateTimeParseException e) {
448	                throw new InvalidClaimException("The date is not a date");
449	            }
450	        }
451	        String note = request.note() == null ? "" : request.note().trim();
452	        String ref = request.ref() == null ? "" : request.ref().trim();
453	        return new ValidClaim(amount, date, note, request.user(), corrects, ref.isEmpty() ? null : ref, tags(request.tags()));
454	    }
455	    /** A claim's tags from the form's comma separated text: each trimmed and lower-cased, blanks and repeats
456	     *  dropped, sorted and joined by commas; null when there are none. */
457	    static String tags(String raw) {
458	        if (raw == null) return null;
459	        java.util.TreeSet<String> tags = new java.util.TreeSet<>();
460	        for (String tag : raw.split(",")) {
461	            String t = tag.trim().toLowerCase(java.util.Locale.ROOT);
462	            if (!t.isEmpty()) tags.add(t);
463	        }
464	        return tags.isEmpty() ? null : String.join(",", tags);
465	    }
466	    /** The claim form's amount: with at most two decimals; a negative one is a correction. */
467	    static BigDecimal signedAmount(String raw) throws InvalidClaimException {
468	        String amount = raw == null ? "" : raw.trim();
469	        if (!SIGNED_AMOUNT.matcher(amount).matches()) {
470	            throw new InvalidClaimException("The amount must have at most two decimals");
471	        }
472	        return new BigDecimal(amount).setScale(2);
473	    }
474	    /** The number of the claim a correction corrects; null when blank. */
475	    static String corrects(String raw) throws InvalidClaimException {
476	        String corrects = raw == null ? "" : raw.trim();
