517	        if (periods.isClosed(claim.getSheetId(), claim.getPeriodDate())) {
518	            throw new InvalidClaimException("No claim whose due-by is inside a closed period can be edited");
519	        }
520	        Person person = people.find(claim.getSheetId(), claim.getPersonId());
521	        if (person != null && !person.allowsClaimOn(date)) {
522	            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
523	        }
524	        ValidateClaim.checkCorrects(request, claim.getSheetId(), claim.getPersonId(), claims);
525	        ValidateClaim.checkRef(request.ref(), claim.getSheetId(), claim.getId(), claims);
526	        claim.setAmount(request.amount());
527	        claim.setRef(request.ref());
