508	 * Adds a DRAFT claim dated the sheet's today, with an empty note, for the named person (name
509	 * compared as the person form compares it), first adding the person with grade A when no one on
510	 * the sheet has that name. One change: a refused claim leaves no new person behind.
511	 */
512	public class SaveQuickClaim {
513	    private static final String GRADE = "A";
514	    public void save(@PathVariable("sheetId") String sheetId, @Val ValidQuickClaim request, People people, Claims claims,
515	            Sheets sheets, Periods periods, Audit audit, @Val RollupFigures before, Rollup rollup,
516	            net.officefloor.hq.app.setting.Settings settings, ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays,
517	            ObjectResponse<ResponseEntity<ClaimResponse>> response) throws InvalidClaimException {
518	        LocalDate date = settings.claimDate(sheetId);
519	        Person person = people.findByName(sheetId, request.name());
520	        // Refuse before anything is written: the claim's period goes by the due-by it would be fixed with.
521	        LocalDate dueBy = holidays.dueBy(sheetId, date, person != null
522	                ? settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date)
523	                : settings.termsFor(sheetId, GRADE, date));
524	        if (periods.isClosed(sheetId, dueBy)) {
525	            throw new InvalidClaimException("No claim can be added inside a closed period");
526	        }
527	        if (person != null && !person.allowsClaimOn(date)) {
528	            throw new InvalidClaimException("No claim can be dated after the person's retirement date");
529	        }
530	        RollupFigures beforeClaim = before;
531	        if (person == null) {
532	            person = people.add(sheetId, request.name(), GRADE);
533	            audit.recordOnCommit("PERSON_ADDED sheet=" + sheetId + " by=" + request.user()
534	                    + " name=" + person.getName() + " grade=" + person.getGrade());
535	            rollup.recordChanges(sheetId, request.user(), before);
536	            beforeClaim = rollup.figures(sheetId);
537	        }
538	        Claim claim = claims.add(sheetId, person.getId(), request.amount(), date, "", dueBy);
539	        log.record(claim, person, request.user());
540	        audit.recordOnCommit(ClaimAudit.line("CLAIM_ADDED", request.user(), person, claim, claim.getNumber()));
