/**
 * Splits the paste into lines of name,amount,date,note (the note may hold commas, the date may be
 * blank, the note absent) and checks each by the claim form's rules. Blank lines are skipped; a paste
 * with no claim in it is refused.
 */
public class ValidatePasteClaims {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody PasteClaimsRequest request, Out<ValidPasteClaims> body, Settings settings)
            throws InvalidClaimException, ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        String text = request.text() == null ? "" : request.text();
        List<ValidPasteClaims.Line> lines = new ArrayList<>();
        int number = 0;
        for (String raw : text.split("\\r?\\n")) {
            number++;
            if (raw.isBlank()) continue;
            String[] fields = raw.split(",", 4);
            if (fields.length < 2) {
                throw new InvalidClaimException("Line " + number + ": a line is name,amount,date,note");
            }
            String name = fields[0].trim();
            if (name.isEmpty()) {
                throw new InvalidClaimException("Line " + number + ": a name is required");
            }
            // A note ending " #<reference>" gives the claim's reference: that part is not the note.
            String note = fields.length > 3 ? fields[3].trim() : "";
            String ref = null;
            int hash = note.lastIndexOf(" #");
            if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
                ref = note.substring(hash + 2);
                note = note.substring(0, hash);
            }
            ClaimRequest claim = new ClaimRequest(fields[1], fields.length > 2 ? fields[2] : "", note, request.user(), null, ref, null);
            try {
                lines.add(new ValidPasteClaims.Line(name, ValidateClaim.check(claim)));
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Line " + number + ": " + e.getMessage());
            }
        }
        java.util.Set<String> refs = new java.util.HashSet<>();
        for (ValidPasteClaims.Line line : lines) {
            String ref = line.claim().ref();
            if (ref != null && !refs.add(ref.toLowerCase(java.util.Locale.ROOT))) {
                throw new InvalidClaimException("The reference " + ref + " is given twice in the paste");
            }
        }
        if (lines.isEmpty()) {
            throw new InvalidClaimException("Nothing to paste: give one claim per line");
        }
        body.set(new ValidPasteClaims(lines, request.user()));
    }
}
=== claim/SavePasteClaims.java
/**
 * Adds the pasted claims as DRAFTs, in order, each audited as CLAIM_ADDED. Every line is checked
 * against the sheet first (the person is on the sheet, matched as names are compared; the date is not
 * inside a closed period nor after the person's retirement), so one refused line writes nothing.
 */
public class SavePasteClaims {
    public void save(@PathVariable("sheetId") String sheetId, @Val ValidPasteClaims request, People people, Claims claims,
            Sheets sheets, Periods periods, Audit audit, @Val RollupFigures before, Rollup rollup, Settings settings,
            ClaimLog log, net.officefloor.hq.app.holiday.Holidays holidays, ObjectResponse<PasteClaimsResponse> response) throws InvalidClaimException {
        LocalDate today = settings.claimDate(sheetId);
        List<Person> persons = new ArrayList<>();
        List<LocalDate> dates = new ArrayList<>();
        int number = 0;
        for (ValidPasteClaims.Line line : request.lines()) {
            number++;
            Person person = people.findByName(sheetId, line.name());
            if (person == null) {
                throw new InvalidClaimException("Claim " + number + ": no one on the sheet is named " + line.name());
            }
            LocalDate date = line.claim().date() != null ? line.claim().date() : today;
            LocalDate dueBy = holidays.dueBy(sheetId, date, settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date));
            if (periods.isClosed(sheetId, dueBy)) {
                throw new InvalidClaimException("Claim " + number + ": no claim can be added inside a closed period");
            }
            if (!person.allowsClaimOn(date)) {
                throw new InvalidClaimException("Claim " + number + ": no claim can be dated after the person's retirement date");
            }
            try {
                ValidateClaim.checkRef(line.claim().ref(), sheetId, null, claims);
            } catch (InvalidClaimException e) {
                throw new InvalidClaimException("Claim " + number + ": " + e.getMessage());
            }
            persons.add(person);
            dates.add(date);
        }
        for (int i = 0; i < request.lines().size(); i++) {
            ValidClaim valid = request.lines().get(i).claim();
            Person person = persons.get(i);
            LocalDate date = dates.get(i);
            Claim claim = claims.add(sheetId, person.getId(), valid.amount(), date, valid.note(), null,
                    holidays.dueBy(sheetId, date, settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date)), valid.ref());
            log.record(claim, person, request.user());
            audit.recordOnCommit(ClaimAudit.added(request.user(), person, claim));
            LateEntry.mark(claim, person, request.user(), claims, periods, audit);
        }
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new PasteClaimsResponse(request.lines().size()));
    }
}
