                        || periods.isClosed(sheetId, claim.getPeriodDate())) {
                    continue;
                }
                try {
                    ApplyClaimStatus.refuseNoteless(claim, sheets, people, rates, settings,
                            Rounding.of(claim, settings.policyDate(sheetId)));
                } catch (ClaimStatusRefusedException e) {
                    continue;
